<!DOCTYPE html>
<html lang="{{ str_replace('_', '-', app()->getLocale()) }}">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
    <link rel="stylesheet" href="{{ config('api.basics.cdn') }}/theme/newUI/css/ionic.bundle.css">
    <title>{{ config('app.name') }}</title>
</head>
<body>
<speedAppleSignV2></speedAppleSignV2>
</body>
<script>
    /**
     * v2-2.0.0 起新增图标自定义
     * 底部图标替换说明：
     * 图标路径：/public/theme/newUI/svg 目录
     * 图标格式：svg
     * 默认图标使用来源：https://www.iconfont.cn
     * 请根据自己需求替换 svg 目录下对应文件即可
     **/
    /**
     * 压缩推荐设置：
     * iconCompressHeightWidth = 256
     * iconCompressMimeType = image/jpeg
     * iconCompressibility = 0
     * 设置 image/jpeg 原因、如果用户上传透明 png 图片，那么 App 桌面图标透明部分会是黑色，设置image/jpeg则会填充白色
     *
     * 【以上推荐设置实测 8.2 MB 图片压缩后只有 9 KB，并且不影响图标显示】
     * 【注：请根据自己喜好以及服务器配置进行设置，详情结果请自行测试】
     **/
    window.customConfig = {
        siteAPI: '{{ config('app.url') }}',         // 对接接口【此处一般无需修改、按默认值即可】
        siteToken: '',                              // 分站令牌【主站留空、分站配置此项完成对接】
        /**
         * 获取 UDID 描述文件说明
         * 请自行下载保存：open.mobileprovision 到您的网站下载（自动跳转手机设置描述文件）
         * 请自行下载保存修改：/api/udid.mobileconfig 到您的网站下载（获取设备码描述文件）
         **/

        /**
         * 链接相关
         **/
        buyURL: '',                                 // 卡密购买跳转地址【可留空、留空不显示】
        tutorialURL: '',                            // 使用教程跳转地址【可留空、留空不显示】
        feedBackURL: '',                            // 问题反馈跳转地址【可留空、留空不显示】
        groupChatRUL: '',                           // 加入群聊跳转地址【可留空、留空不显示】
        /**
         * 显示开关
         **/
        displayHelpList: true,                      // 是否显示帮助列表 【false=隐藏、true=显示】
        displayAboutUSItem: true,                   // 是否显示关于我们 【false=隐藏、true=显示】关于我们中的官方自定义URL
        displayCertDownload: true,                  // 是否显示证书下载【false=隐藏、true=显示】
        displayCertDetection: true,                 // 是否显示证书检测【false=隐藏、true=显示】
        displayAgentManagement: true,               // 是否显示管理管理【false=隐藏、true=显示】
        /**
         * 基础配置
         **/
        themeStyle: 'ios',                          // 主题风格【android=安卓风格、ios=苹果风格】
        debug: true,                                // 调试模式 控制台日志输出【false=关闭、true=开启】关闭时调试卡死
        autoOpenSettings: 3000,                     // 获取设备码时自动打开设置时间【3000=3秒，iOS17起不支持自动打开、会有弹框引导】
        /**
         * 签名配置
         **/
        changeNameSwitch: true,                     // 当后台开启前端修改功能时、是否打开修改名称【false=关闭、true=开启】
        changeIconSwitch: true,                     // 当后台开启前端修改功能时、是否打开修改图标【false=关闭、true=开启】
        changeAppIDSwitch: true,                    // 当后台开启前端修改功能时、是否打开修改AppID【false=关闭、true=开启】
        changeVersionSwitch: true,                  // 当后台开启前端修改功能时、是否打开修改版本号【false=关闭、true=开启】
        changeMultipleSwitch: true,                 // 当后台开启前端修改功能时、是否打开应用多开签名开关【false=关闭、true=开启】
        changeMinOSSwitch: true,                    // 当后台开启前端修改功能时、是否打开修改移除版本限制【false=关闭、true=开启】
        changeUrlJumpSwitch: true,                  // 当后台开启前端修改功能时、是否打开修改移除应用跳转【false=关闭、true=开启】
        changeFileAccessSwitch: true,               // 当后台开启前端修改功能时、是否打开修改开启文件访问【false=关闭、true=开启】
        changeDownloadIPASwitch: true,              // 应用安装列表开启在线下载安装包【false=关闭、true=开启】
        iconCompressHeightWidth: 256,               // 压缩图片高度与宽度限制【例如：256、图片最大为 256*256】
        iconCompressibility: 0,                     // 压缩率 0-1【例如：0、0.2、0.4、0.6、0.8、1 其中 0 压缩后图片最小、1 压缩后最大】
        iconCompressMimeType: 'image/jpeg',         // 压缩类型，推荐：image/jpeg【可用：image/jpeg、image/png】
        /**
         * 备案相关
         **/
        icpbeian: '{{ config('api.basics.icpbeian') }}',                               // 例子：京ICP备12345678号
        icplicence: '{{ config('api.basics.icplicence') }}',                           // 例子：京B2-12345678
        wanganbeian: '{{ config('api.basics.wanganbeian') }}',                         // 例子：京公网安备12345678900000
    }

    /**
     * 为了方便用户快速自定义所有页面内容
     * 删除了原有的多语言包方法，原因：多语言包没次都要执行一次请求，占用资源、影响用户体验
     *
     * 所以本处改为全局替换方法、网站管理员可以通过此方法修改此 UI 页面所有文字、包括服务器回调的信息
     * 使用方法如下：
     *
     * 修改单个：const langPack = { '签名下载': '在线签名', }
     * 其中的 “签名下载” 为原有显示文本，“在线签名” 为要替换的文字
     *
     * 修改多个：const langPack = { '签名下载': '在线签名', '证书检测': '在线检测', '查询签名': '在线查询', '帮助中心': '在线帮助', }
     *
     * 如果您不需要修改、也可以将：const langPack = {} 删除或注释
     **/
    window.langPack = {
        // '签名下载': '在线签名', // 这里使用注释、将不执行修改
    }
</script>
